const defaultState={saved:[],requests:{},created:[],profile:{name:'You',city:'',gender:'',age:false,bio:''},blocked:[],reports:[]};
let state;try{const raw=JSON.parse(localStorage.getItem('tripling-v1'));state={...defaultState,...raw,profile:{...defaultState.profile,...raw?.profile}};if(!Array.isArray(state.saved)||!Array.isArray(state.created)||!state.requests)throw Error();}catch{state=structuredClone(defaultState)}
let storageWarning=false;function persist(){try{localStorage.setItem('tripling-v1',JSON.stringify(state));}catch{if(!storageWarning){storageWarning=true;toast('Browser storage is unavailable. Changes last for this visit only.');}}}
let view='discover',category='All trips',maxBudget=25000,travelMode='',womenFilter=false,visibleCount=6,currentTrip=null;
const trips=()=>[...state.created,...seeds].filter(t=>!state.blocked.includes(t.id));
const money=n=>'₹'+Number(n).toLocaleString('en-IN');
const date=d=>new Date(d+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short'});
const duration=t=>Math.round((new Date(t.end)-new Date(t.start))/86400000)+1;
const range=t=>`${date(t.start)} – ${date(t.end)}`;
const modal=$('#modal');let focusBefore=null;
function openModal(html){focusBefore=document.activeElement;$('#modal-content').innerHTML=html;icons(modal);if(!modal.open)modal.showModal();modal.scrollTop=0;setTimeout(()=>{const el=modal.querySelector('[autofocus]')||modal.querySelector('.modal-close');el?.focus();},0)}
function closeModal(){modal.close();focusBefore?.focus();}
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function card(t){const saved=state.saved.includes(t.id),owned=state.created.some(c=>c.id===t.id),pending=state.requests[t.id];return `<article class="trip-card"><div class="card-image"><img src="assets/${esc(t.image)}.jpg" alt="${esc(t.destination)} travel inspiration" loading="lazy"><span class="match-badge" title="Illustrative compatibility in this demo; not a safety rating">${icon('spark')} ${t.score}% travel fit</span><button class="save-button ${saved?'saved':''}" data-save="${esc(t.id)}" aria-label="${saved?'Unsave':'Save'} ${esc(t.title)}" aria-pressed="${saved}">${icon('bookmark')}</button><span class="image-label">${icon('pin')} ${esc(t.destination)}, India</span></div><div class="card-content"><div class="card-tags">${t.tags.map(tag=>`<span class="tag ${tag==='Women only'?'women':''}">${esc(tag)}</span>`).join('')}</div><button class="card-title" data-trip="${esc(t.id)}">${esc(t.title)}</button><p class="card-route">${esc(t.from)} <span aria-hidden="true">→</span> ${esc(t.destination)}</p><div class="card-info"><span>${icon('calendar')} ${range(t)}</span><span>${icon('clock')} ${duration(t)} days</span></div><div class="card-cost"><strong>${money(t.min)}–${money(t.max).replace('₹','')}</strong><span>/ person</span><span>${t.seats} spots open</span></div><div class="card-footer"><span class="avatar host-avatar">${esc(owned?state.profile.name.slice(0,2).toUpperCase():t.initials)}</span><div class="host-name">Planned by <strong>${esc(owned?'you':t.host)}</strong><span>${owned?'Your travel plan':'Sample traveler'}</span></div><button class="card-cta" data-trip="${esc(t.id)}">View trip ${icon('arrow-up-right')}</button></div>${view==='my-trips'?`<div class="my-card-status">${owned?`<p>Your trip · ${t.seats} open spots</p><button data-delete-trip="${esc(t.id)}">Delete trip</button>`:`<span class="request-status">Awaiting approval · demo</span><button data-cancel="${esc(t.id)}">Cancel request</button>`}</div>`:''}</div></article>`}
function render(){let list=trips();const dest=$('#destination').value.trim().toLowerCase(),origin=$('#origin').value.trim().toLowerCase(),when=$('#departure').value;
if(view==='saved')list=list.filter(t=>state.saved.includes(t.id));if(view==='my-trips')list=list.filter(t=>state.requests[t.id]||state.created.some(c=>c.id===t.id));
if(view==='discover'){list=list.filter(t=>(!dest||`${t.destination} ${t.title}`.toLowerCase().includes(dest))&&(!origin||t.from.toLowerCase().includes(origin))&&(!when||(t.start<=when&&t.end>=when))&&(category==='All trips'||(category==='Women only'?t.women:category==='Adventure'?t.category==='Adventure'||t.tags.includes('Adventure'):category==='Weekend'?t.category==='Weekend'||t.tags.includes('Weekend'):t.category===category))&&t.min<=maxBudget&&(!travelMode||t.mode.toLowerCase().includes(travelMode))&&(!womenFilter||t.women));}
const sort=$('#sort').value;list.sort((a,b)=>sort==='soonest'?a.start.localeCompare(b.start):sort==='budget'?a.min-b.min:b.score-a.score);
$('#trip-grid').innerHTML=list.slice(0,visibleCount).map(card).join('');$('#empty').hidden=!!list.length;$('#results-count').innerHTML=`<strong>${list.length} ${list.length===1?'trip':'trips'}</strong> ${view==='saved'?'saved for another day':view==='my-trips'?'in your travel plans':'with room for a new story'}`;
$('#load-more-wrap').hidden=view!=='discover'||!list.length;$('#load-more').hidden=list.length<=visibleCount;
$('#filter-count').hidden=!(maxBudget<25000||travelMode||womenFilter);$('#filter-count').textContent=[maxBudget<25000,!!travelMode,womenFilter].filter(Boolean).length;
$('#request-count').textContent=Object.keys(state.requests).length+state.created.length;$('#request-count').hidden=!(Object.keys(state.requests).length+state.created.length);
$('.profile-button').childNodes[0].textContent=state.profile.name.slice(0,1).toUpperCase();
icons($('#trip-grid'));}
function setView(next){view=['discover','saved','my-trips'].includes(next)?next:'discover';$('#discovery-intro').hidden=view!=='discover';$('.filter-row').hidden=view!=='discover';$('.why').hidden=view!=='discover';$('.create-banner').hidden=view!=='discover';$('.explore').classList.toggle('tab-intro',view!=='discover');
$('#section-title').textContent=view==='saved'?'Your someday, saved.':view==='my-trips'?'Your next stories start here.':'Good trips need good company.';$('#section-eyebrow').textContent=view==='saved'?'KEEP THE GOOD PLANS CLOSE':view==='my-trips'?'YOUR TRAVEL PLANS':'FIND YOUR NEXT CHAPTER';$('#section-description').textContent=view==='saved'?'A little inspiration for your next escape.':view==='my-trips'?'Trips you’ve created and requests you’re waiting on.':'Real plans. Like-minded travelers. A place for you.';
$('#empty h3').textContent=view==='saved'?'Your next adventure is waiting.':view==='my-trips'?'Every great trip starts with a plan.':'A different adventure awaits.';$('#empty p').textContent=view==='saved'?'Tap the bookmark on any trip to keep it here.':view==='my-trips'?'Create a trip or send a join request to get started.':'Try another destination or clear your filters to see more trips.';
document.querySelectorAll('[data-view]').forEach(el=>{el.classList.toggle('active',el.dataset.view===view);if(el.dataset.view===view)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current')});visibleCount=6;render();}
function detail(id){const t=trips().find(t=>t.id===id);if(!t)return;currentTrip=id;const owned=state.created.some(c=>c.id===id),pending=state.requests[id];openModal(`<img class="modal-photo" src="assets/${esc(t.image)}.jpg" alt="${esc(t.destination)} scenery"><div class="modal-pad"><div class="detail-tags">${t.tags.map(tag=>`<span class="tag ${tag==='Women only'?'women':''}">${esc(tag)}</span>`).join('')}</div><h2 id="modal-title">${esc(t.title)}</h2><p class="detail-lead">${esc(t.description)}</p><div class="detail-grid"><div>${icon('route')}<span><small>The route</small>${esc(t.from)} → ${esc(t.destination)}</span></div><div>${icon('calendar')}<span><small>Travel dates</small>${range(t)}</span></div><div>${icon('users')}<span><small>Your crew</small>${t.total-t.seats} going · ${t.seats} spots open</span></div><div>${icon('compass')}<span><small>Travel mode</small>${esc(t.mode)}</span></div></div><div class="detail-section"><h3>The loose plan</h3><p>${esc(t.plan)}</p></div><div class="detail-section"><h3>Budget for the journey</h3><p><strong>${money(t.min)}–${money(t.max)}</strong> per person, estimated for transport, stay, and daily expenses. Confirm costs together. Tripling does not collect payments.</p></div><div class="detail-section"><h3>A few shared ground rules</h3><p>${esc(t.rules)}</p></div><div class="detail-host"><span class="avatar">${esc(t.initials)}</span><div><strong>Planned by ${esc(owned?'you':t.host)}</strong><p>${owned?'Your locally saved trip':'Sample host · illustrative trip, not a real travel listing'}</p></div></div><p class="notice">${t.women?'Women-only membership. Eligibility in this preview is self-declared; it is not identity verification. ':''}Travel-fit percentages are illustrative compatibility signals, never a guarantee of safety. Your phone number and exact address are not shown.</p><div class="modal-actions">${owned?`<button class="primary" data-action="my-trips">View my trips ${icon('arrow-right')}</button>`:pending?`<button class="primary" disabled>Request pending in this preview</button><button class="secondary" data-cancel="${esc(id)}">Cancel request</button>`:`<button class="primary" data-join="${esc(id)}">Request to join ${icon('arrow-right')}</button>`}<button class="secondary" data-save="${esc(id)}">${icon('bookmark')} ${state.saved.includes(id)?'Saved':'Save trip'}</button></div>${!owned?`<button class="report-link" data-report="${esc(id)}">Report or hide this trip</button>`:''}</div>`)}
function join(id){const t=trips().find(t=>t.id===id);if(!t)return;if(t.women&&state.profile.gender!=='woman'){openModal(`<div class="modal-pad"><div class="eyebrow">YOUR CHOICE, RESPECTED</div><h2 id="modal-title">This is a women-only trip.</h2><p>Only travelers who identify as women can request to join. Set your eligibility in your demo profile to continue.</p><p class="notice">This prototype uses self-declaration only. It does not verify anyone’s identity.</p><div class="modal-actions"><button class="primary" data-action="profile">Open demo profile</button><button class="secondary" data-trip="${esc(id)}">Back to trip</button></div></div>`);return;}
openModal(`<div class="modal-pad"><div class="eyebrow">START WITH A HELLO</div><h2 id="modal-title">A good trip starts with good company.</h2><p>Introduce yourself to ${esc(t.host)} for <strong>${esc(t.title)}</strong>.</p><form id="join-form" data-id="${esc(id)}"><div class="form-grid"><label class="form-field full">Your name<input name="name" required maxlength="50" value="${state.profile.name==='You'?'':esc(state.profile.name)}" placeholder="What should the crew call you?" autofocus></label><label class="form-field full">A little about you and your travel plans<textarea name="note" required minlength="15" maxlength="600" placeholder="Why does this trip feel like your kind of plan?"></textarea></label></div><label class="check-label"><input type="checkbox" name="adult" required ${state.profile.age?'checked':''}> I am 18 or older and agree to respect personal boundaries and the group’s travel rules.</label><p class="notice">Demo only: this request is saved in your browser. No host will receive it. Group chat becomes available only after a real organizer approves a request in the future connected version.</p><div class="modal-actions"><button type="submit" class="primary">Save demo join request ${icon('arrow-right')}</button><button type="button" class="secondary" data-trip="${esc(id)}">Back</button></div></form></div>`)}
function create(){openModal(`<div class="modal-pad"><div class="eyebrow">YOU BRING THE PLAN</div><h2 id="modal-title">Make room for a new adventure.</h2><p>Give your crew a feel for the trip. You can keep the details flexible.</p><form id="create-form"><div class="form-grid"><label class="form-field full">Give your trip a name<input name="title" required maxlength="65" placeholder="A weekend in the mountains…" autofocus></label><label class="form-field">Starting from<input name="from" required maxlength="40" placeholder="e.g. Delhi"></label><label class="form-field">Destination<input name="destination" required maxlength="40" placeholder="e.g. Manali"></label><label class="form-field">Departure<input type="date" name="start" min="${today()}" required></label><label class="form-field">Return<input type="date" name="end" min="${today()}" required></label><label class="form-field">Minimum budget / person (₹)<input name="min" type="number" min="0" max="1000000" required placeholder="5000"></label><label class="form-field">Maximum budget / person (₹)<input name="max" type="number" min="0" max="1000000" required placeholder="8000"></label><label class="form-field">Already going (including you)<input name="going" type="number" min="1" max="19" value="1" required></label><label class="form-field">Open spots<input name="seats" type="number" min="1" max="19" value="2" required></label><label class="form-field">Travel style<select name="category"><option>Mountains</option><option>Beach</option><option>Adventure</option><option>Weekend</option></select></label><label class="form-field">Travel mode<select name="mode"><option>Bus</option><option>Train</option><option>Shared cab</option><option>Self-drive</option><option>Flight</option></select></label><label class="form-field full">Tell us about the plan<textarea name="description" required minlength="25" maxlength="1200" placeholder="The places, the pace, and the people you’d love to share it with."></textarea></label><label class="form-field full">Who can request to join?<select name="group"><option value="mixed">All eligible travelers (18+)</option><option value="women">Women only</option></select></label></div><label class="check-label"><input type="checkbox" required name="adult"> I am 18 or older. I’ll use public meeting points and respect travelers’ privacy.</label><p id="create-error" class="form-error" role="alert"></p><p class="notice">This preview saves your trip on this device only. All join requests require organizer approval; your trip does not collect money or publish contact details.</p><div class="modal-actions"><button class="primary" type="submit">Create my trip ${icon('arrow-up-right')}</button></div></form></div>`)}
function profile(){openModal(`<div class="modal-pad"><div class="eyebrow">THE PERSON BEHIND THE PLAN</div><h2 id="modal-title">Your traveler profile.</h2><div class="profile-preview"><span class="avatar">${esc(state.profile.name.slice(0,1))}</span><div><strong>${esc(state.profile.name)}</strong><p>Demo profile · not verified</p></div></div><form id="profile-form"><div class="form-grid"><label class="form-field full">Name<input name="name" required maxlength="50" value="${esc(state.profile.name==='You'?'':state.profile.name)}" placeholder="Your name" autofocus></label><label class="form-field">Home city (optional)<input name="city" value="${esc(state.profile.city)}" maxlength="40" placeholder="City only, no exact address"></label><label class="form-field">Group eligibility<select name="gender"><option value="">Prefer not to say</option><option value="woman" ${state.profile.gender==='woman'?'selected':''}>I identify as a woman</option><option value="other" ${state.profile.gender==='other'?'selected':''}>Other / not eligible for women-only trips</option></select></label><label class="form-field full">Your travel style<textarea name="bio" maxlength="500" placeholder="A little about how you like to travel…">${esc(state.profile.bio)}</textarea></label></div><label class="check-label"><input type="checkbox" name="adult" required ${state.profile.age?'checked':''}> I confirm I am 18 or older.</label><p class="notice">This is a local demo profile, not an account. No phone or identity verification has been performed. Please don’t enter private contact details.</p><div class="modal-actions"><button class="primary" type="submit">Save profile ${icon('check')}</button></div></form></div>`)}
function safety(){openModal(`<div class="modal-pad"><div class="eyebrow">A LITTLE TRUST GOES A LONG WAY</div><h2 id="modal-title">Your journey. Your boundaries.</h2><p>Getting to know someone is part of the journey. Take your time before committing to travel together.</p><ul class="safety-list"><li>${icon('users')}<div><strong>Meet your crew first</strong><p>Have a video call, discuss the plan, and arrange your first meeting in a busy public place.</p></div></li><li>${icon('lock')}<div><strong>Keep personal details yours</strong><p>Avoid sharing your home address, identity documents, live location, or private contact details in public trip descriptions.</p></div></li><li>${icon('shield')}<div><strong>Trust has no shortcut</strong><p>A travel-fit score measures shared preferences. Even future verification badges won’t guarantee someone’s behavior or safety.</p></div></li><li>${icon('flag')}<div><strong>You can always change your mind</strong><p>Leave a plan if you feel uncomfortable. Use “Report or hide this trip” on a listing to hide it in this preview.</p></div></li></ul><p class="notice">In an emergency in India, call 112 or contact local emergency services. Share your plans with a trusted person. This prototype does not provide emergency monitoring or a staffed reporting service.</p><div class="modal-actions"><button class="primary" data-action="close">Got it. Let’s explore.</button></div></div>`)}
function filters(){openModal(`<div class="modal-pad"><div class="eyebrow">A PLAN THAT FEELS LIKE YOU</div><h2 id="modal-title">Find your kind of trip.</h2><form id="filter-form"><div class="form-grid"><label class="form-field full">Maximum budget per person<select name="budget"><option value="25000">Any budget up to ₹25,000</option><option value="5000">Up to ₹5,000</option><option value="10000">Up to ₹10,000</option><option value="15000">Up to ₹15,000</option></select></label><label class="form-field full">Travel mode<select name="mode"><option value="">Any travel mode</option><option value="bus">Bus</option><option value="train">Train</option><option value="cab">Cab</option><option value="self-drive">Self-drive</option><option value="flight">Flight</option></select></label></div><label class="check-label"><input type="checkbox" name="women" ${womenFilter?'checked':''}> Show women-only trips</label><p class="notice">Budget filters use each trip’s minimum estimated cost. Final expenses are agreed between travelers.</p><div class="modal-actions"><button type="submit" class="primary">Show matching trips</button><button type="button" class="secondary" data-action="reset-filters">Reset filters</button></div></form></div>`);$('#filter-form [name=budget]').value=String(maxBudget);$('#filter-form [name=mode]').value=travelMode;}
function reset(){category='All trips';maxBudget=25000;travelMode='';womenFilter=false;$('#search-form').reset();document.querySelectorAll('[data-category]').forEach(b=>b.classList.toggle('selected',b.dataset.category===category));if(view!=='discover'){location.hash='discover';setView('discover')}render()}
function report(id){openModal(`<div class="modal-pad"><div class="eyebrow">YOUR SPACE. YOUR CHOICE.</div><h2 id="modal-title">Report or hide this trip.</h2><p>Hide the listing from your discovery feed. This preview records your note locally; it does not send it to a moderation team.</p><form id="report-form" data-id="${esc(id)}"><div class="form-grid"><label class="form-field full">Reason<select name="reason"><option>I don’t want to see this trip</option><option>Spam or commercial promotion</option><option>Harassment or inappropriate content</option><option>Safety concern</option></select></label><label class="form-field full">More context (optional)<textarea name="note" maxlength="600" placeholder="Please do not include sensitive personal details."></textarea></label></div><p class="notice">For an immediate danger, contact emergency services. No live moderation or emergency response is available in this preview.</p><div class="modal-actions"><button class="primary" type="submit">Record note & hide trip</button><button class="secondary" type="button" data-trip="${esc(id)}">Back</button></div></form></div>`)}
document.addEventListener('click',e=>{const b=e.target.closest('button, a');if(!b)return;
if(b.dataset.save){const id=b.dataset.save;state.saved=state.saved.includes(id)?state.saved.filter(v=>v!==id):[...state.saved,id];persist();render();if(modal.open)detail(id);toast(state.saved.includes(id)?'Saved for your next adventure.':'Trip removed from saved.');return;}
if(b.dataset.trip){detail(b.dataset.trip);return}if(b.dataset.join){join(b.dataset.join);return}if(b.dataset.cancel){delete state.requests[b.dataset.cancel];persist();render();if(modal.open)detail(b.dataset.cancel);toast('Demo join request canceled.');return}if(b.dataset.deleteTrip){const t=state.created.find(t=>t.id===b.dataset.deleteTrip);openModal(`<div class="modal-pad"><h2 id="modal-title">Delete your trip?</h2><p>“${esc(t?.title)}” will be removed from this device.</p><div class="modal-actions"><button class="primary" data-confirm-delete="${esc(b.dataset.deleteTrip)}">Delete trip</button><button class="secondary" data-action="close">Keep it</button></div></div>`);return}if(b.dataset.confirmDelete){state.created=state.created.filter(t=>t.id!==b.dataset.confirmDelete);state.saved=state.saved.filter(id=>id!==b.dataset.confirmDelete);persist();closeModal();render();toast('Trip deleted from this device.');return}
if(b.dataset.report){report(b.dataset.report);return}if(b.dataset.category){category=b.dataset.category;document.querySelectorAll('[data-category]').forEach(el=>el.classList.toggle('selected',el===b));render();return}if(b.dataset.destination){$('#destination').value=b.dataset.destination;$('#search-form').requestSubmit();return}
const action=b.dataset.action;if(!action)return;
({close:closeModal,create,profile,safety,filters,reset,'reset-filters':()=>{maxBudget=25000;travelMode='';womenFilter=false;closeModal();render()},'my-trips':()=>{closeModal();location.hash='my-trips';setView('my-trips')},'demo-info':()=>openModal(`<div class="modal-pad"><div class="eyebrow">THE FIRST CHAPTER</div><h2 id="modal-title">Meet your Tripling preview.</h2><p>Explore sample trips, save favorites, create your own trip, and try a join request. Your changes stay in this browser.</p><p>Hosts, travel-fit scores, and existing listings are illustrative. No real bookings, messages, payments, verification, or travel arrangements are made here.</p><p class="notice">Real accounts, shared data, organizer approvals, group chat, and staffed moderation need a connected backend before launch.</p><div class="modal-actions"><button class="primary" data-action="close">Start exploring</button></div></div>`)})[action]?.();});
$('#search-form').addEventListener('submit',e=>{e.preventDefault();render();$('.explore').scrollIntoView({behavior:'smooth',block:'start'})});$('#sort').addEventListener('change',render);$('#load-more').addEventListener('click',()=>{visibleCount+=6;render()});
document.addEventListener('submit',e=>{const f=e.target;if(!['join-form','create-form','profile-form','filter-form','report-form'].includes(f.id))return;e.preventDefault();const d=Object.fromEntries(new FormData(f));
if(f.id==='join-form'){const t=trips().find(t=>t.id===f.dataset.id);if(!t)return;if(t.women&&state.profile.gender!=='woman'){join(t.id);return}if(!d.name.trim()||d.note.trim().length<15){toast('Add your name and an introduction of at least 15 characters.');return}state.profile.name=d.name.trim();state.profile.age=true;state.requests[t.id]={note:d.note.trim(),at:new Date().toISOString()};persist();closeModal();render();toast('Demo request saved. Find it in My trips.');}
if(f.id==='profile-form'){if(!d.name.trim()){toast('Please add your name.');return}state.profile={name:d.name.trim(),city:d.city.trim(),gender:d.gender,bio:d.bio.trim(),age:!!d.adult};persist();closeModal();render();toast('Your demo profile is ready.');}
if(f.id==='filter-form'){maxBudget=Number(d.budget);travelMode=d.mode;womenFilter=!!d.women;closeModal();render();}
if(f.id==='report-form'){state.reports.push({trip:f.dataset.id,reason:d.reason,note:d.note,at:new Date().toISOString()});state.blocked.push(f.dataset.id);persist();closeModal();render();toast('Trip hidden. Your note is saved locally only.');}
if(f.id==='create-form'){const error=$('#create-error');if(!d.title.trim()||!d.from.trim()||!d.destination.trim()||d.description.trim().length<25){error.textContent='Add a trip name, route, and a description of at least 25 characters.';return}if(d.end<d.start){error.textContent='Your return date must be on or after departure.';return}if(d.start<today()){error.textContent='Choose a departure date today or later.';return}if(+d.min>+d.max){error.textContent='Maximum budget must be at least the minimum budget.';return}if(+d.going + +d.seats>20){error.textContent='Keep your group to 20 travelers or fewer for this preview.';return}if(d.group==='women'&&state.profile.gender!=='woman'){error.textContent='To create a women-only trip, first set your eligibility in your profile.';return}
const t={id:'local-'+crypto.randomUUID(),title:d.title.trim(),from:d.from.trim(),destination:d.destination.trim(),start:d.start,end:d.end,min:+d.min,max:+d.max,seats:+d.seats,total:+d.going + +d.seats,category:d.category,tags:[d.category,...(d.group==='women'?['Women only']:['New plan'])],women:d.group==='women',mode:d.mode,description:d.description.trim(),plan:'The detailed itinerary will be agreed together. '+d.description.trim(),rules:'Public meeting points, respectful communication, and organizer approval for every join request. Contact details stay private.',host:state.profile.name,initials:state.profile.name.slice(0,2).toUpperCase(),score:100,image:d.category==='Beach'?'goa':d.category==='Adventure'?'rishikesh':d.category==='Weekend'?'udaipur':'manali'};state.created.unshift(t);state.profile.age=true;persist();closeModal();location.hash='my-trips';setView('my-trips');window.scrollTo({top:0});toast('Your trip is ready, saved on this device.');}
});
window.addEventListener('hashchange',()=>setView(location.hash.slice(1)));icons();setView(location.hash.slice(1)||'discover');
